import assert from 'node:assert/strict';
import{cases,calculate,householdPeriodLedger}from'../../lib/newdoor-current-model.mjs';
const copy=x=>structuredClone(x),near=(a,b)=>{if(a===null||b===null)assert.equal(a,b);else assert(Math.abs(a-b)<1e-10*Math.max(1,Math.abs(b)));};
function own(s){const count=s.budgetUsd*s.allocationShares.employment/s.costPerOfferedPlaceUsd;let inc=null; if(s.income){inc=0;for(const p of s.income.periods){let duration=0;for(let j=0;j<Math.ceil(p.years);j++)duration+=Math.min(1,p.years-j)/(1+s.discountRate)**(p.delayYears+j);for(const b of p.branches){let w=b.paidHours*b.hourlyWageUsd;let rows=[w,-w*b.taxShare,-w*b.benefitDisplacementShare,-b.counterfactualTakeHomeUsd,-b.uncoveredTravelChildcareUsd,b.otherHouseholdNetChangeUsd,-b.incrementalTimeHours*b.timeValueUsd];let d=rows.reduce((v,x)=>v+(x>0?x*s.income.independentShare:x),0);inc+=b.probability*.5*s.income.householdSize*duration*Math.log1p(d/(p.years*p.baselineAnnualHouseholdResourcesUsd));}}inc*=count*s.income.uniqueHouseholdsPerOfferedPlace;}const h=s.health;let health=[h.utilityGain,h.effectiveYears,h.independentShare].includes(null)?null:count*h.utilityGain*h.effectiveYears*(h.utilityGain>0?h.independentShare:1)/(1+s.discountRate)**h.delayYears;const a=x=>s.serviceAdditionality===0?0:x===null||s.serviceAdditionality===null?null:x*s.serviceAdditionality;return{health:a(health),income:a(inc)};}
const rows=cases.map(s=>{const a=calculate(s),b=own(s);near(a.causedHealthQaly,b.health);near(a.causedIncomeHealthyYearEquivalent,b.income);if(b.health!==null&&b.income!==null){const sum=b.health+b.income;near(a.bayIncludingSfCombinedHealthyYearEquivalent,sum*s.bayResidentShare-s.independentGiftHarm.sf-s.independentGiftHarm.restBay);near(a.sfCombinedHealthyYearEquivalent,sum*s.sfResidentShare-s.independentGiftHarm.sf);near(a.allResidenceCombinedHealthyYearEquivalent,sum-Object.values(s.independentGiftHarm).reduce((x,y)=>x+y,0));near(a.sfCombinedHealthyYearEquivalent+a.restBayCombinedHealthyYearEquivalent,a.bayIncludingSfCombinedHealthyYearEquivalent);}return{id:s.id,bay:a.bayIncludingSfCombinedHealthyYearEquivalent,price:a.bayUsdPer10ConditionalCombinedHealthyYearEquivalent};});
let checks=0;function test(fn){fn();checks++;}const base=()=>copy(cases[1]);
for(const change of[s=>s.budgetUsd=100001,s=>s.budgetUsd=Infinity,s=>s.budgetUsd=-1,s=>{s.health.utilityGain=null;s.health.effectiveYears=NaN},s=>{s.health.effectiveYears=null;s.health.independentShare=2},s=>delete s.independentGiftHarm.restBay,s=>s.independentGiftHarm.extra=0,s=>s.independentGiftHarm.sf=NaN,s=>s.income.periods[0].branches[0].probability=.4,s=>s.income.periods.push({...copy(s.income.periods[0]),delayYears:.25}),s=>s.bayResidentShare=.2,s=>s.income.periods[0].branches[0].otherHouseholdNetChangeUsd=-1e8])test(()=>{const s=base();change(s);assert.throws(()=>calculate(s));});
test(()=>{const s=base();s.health.utilityGain=-.0025;s.health.independentShare=0;near(calculate(s).causedHealthQaly,-.00109375);});
test(()=>{const s=base();s.income.independentShare=0;assert(calculate(s).causedIncomeHealthyYearEquivalent<0);});
test(()=>{const s=base();s.income.uniqueHouseholdsPerOfferedPlace=0;s.independentGiftHarm.sf=.002;let a=calculate(s);near(a.causedIncomeHealthyYearEquivalent,0);near(a.sfHealthQaly,.00109375*.45-.002);});
test(()=>{const s=base();s.budgetUsd=0;s.independentGiftHarm.sf=.1;let a=calculate(s);near(a.sfCombinedHealthyYearEquivalent,0);assert.equal(a.sfUsdPer10ConditionalCombinedHealthyYearEquivalent,null);});
test(()=>{const p=copy(base().income.periods[0]);p.years=1.25;p.delayYears=.75;p.discountRate=.03;const expected=own({...base(),income:{...base().income,periods:[p]}}).income;near(calculate({...base(),income:{...base().income,periods:[p]}}).causedIncomeHealthyYearEquivalent,expected);});
test(()=>{const a=calculate(cases[12]),b=calculate(cases[1]);near(a.bayIncludingSfCombinedHealthyYearEquivalent/b.bayIncludingSfCombinedHealthyYearEquivalent,65.0512);assert.equal(a.donorCostUsd,null);assert.equal(a.annualWorkBudgetUsd,6505120);assert.equal(a.socialResourceCostUsd,null);near(a.periodLedgers[0].expectedNetCashChangeUsd,1923.8928);});
test(()=>{const p=copy(base().income.periods[0]);p.branches=[p.branches[2]];p.branches[0].probability=1;const a=householdPeriodLedger({...p,discountRate:.03},3,0);near(a.expectedNetResourceEquivalentChangeUsd,-40);assert(a.healthyYearEquivalentPerOfferedHousehold<0);});
const zeroUnknown=copy(cases[0]);zeroUnknown.budgetUsd=0;
console.log(JSON.stringify({reproducedCases:13,checks,rows,zeroGiftUnknown:calculate(zeroUnknown).bayIncludingSfCombinedHealthyYearEquivalent,remark:'unknown-zero channel remains null; no false positive or harm, but explicit zero modeled-channel semantics can be improved'},null,2));
